export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteResult {
  premium: number;
}

export const quote = (
  customer: Customer,
  items: QuoteItem[],
  contractIndex: number
): QuoteResult => {
  return undefined as unknown as QuoteResult;
};

