export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteResult {
  premium: number;
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

export const quote = (
  customer: Customer,
  items: QuoteItem[],
  contractIndex: number
): QuoteResult => {
  if (items.length === 0) {
    return { premium: 5 };
  }
  const base = BASE_PREMIUMS[items[0].type];
  // Multiply-then-divide by whole numbers (not `* 1.1`) keeps this exact for
  // the bases seen so far — no float epsilon hack needed. Revisit with
  // Math.ceil/rounding once a test produces a genuinely fractional subtotal.
  const subtotal = (base * 11) / 10;
  const premium = subtotal + 5;
  return { premium };
};

