import { describe, it, expect } from "vitest";
import { quote } from "./quote.js";

describe("Quote", () => {
  // Simplest cases
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = quote({ yearsWithMHPCO: 0 }, [], 0);
    expect(result.premium).toBe(5);
  });

  // Base premiums for main items (first insurance, newcomer, no modifiers)
  it("single sword (newcomer) → base 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
    const result = quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }], 0);
    expect(result.premium).toBe(115);
  });
  it("single amulet (newcomer) → base 60 G + 6 G first insurance + 5 G fee = 71 G", () => {
    const result = quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }], 0);
    expect(result.premium).toBe(71);
  });
  it("single staff (newcomer) → base 80 G + 8 G first insurance + 5 G fee = 93 G", () => {
    const result = quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }], 0);
    expect(result.premium).toBe(93);
  });
  it("single potion (newcomer) → base 40 G + 4 G first insurance + 5 G fee = 49 G", () => {
    const result = quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }], 0);
    expect(result.premium).toBe(49);
  });

  // Component block-of-3 rules
  it("2 runes → 50 G base premium (no block)", () => {
    const result = quote(
      { yearsWithMHPCO: 0 },
      [{ type: "rune" }, { type: "rune" }],
      0
    );
    // base 50 + 10% first insurance (5) + 5 fee = 60
    expect(result.premium).toBe(60);
  });
  it("3 runes → 60 G base premium (block applies)", () => {
    const result = quote(
      { yearsWithMHPCO: 0 },
      [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
      0
    );
    // base 60 (block) + 10% first insurance (6) + 5 fee = 71
    expect(result.premium).toBe(71);
  });
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // Item-specific modifiers in isolation
  it.todo("cursed sword → curse surcharge is 50% of the cursed item's base premium, not the policy total");
  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("sword with exactly enchantment 5 and cursed → both surcharges apply");

  // Policy-wide modifiers in isolation
  it.todo("customer with exactly 2 years with MHPCO → loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("newcomer's first quote → first insurance surcharge applies to policy");
  it.todo("customer's second quote in a scenario → follow-up contract discount applies");

  // Modifier scope on multi-item policies
  it.todo(
    "policy with cursed sword (100 G) + plain amulet (60 G) → policy base premium 160 G; curse surcharge 50 G (on sword's base only) → 210 G before fee/policy-wide modifiers"
  );

  // Rounding
  it.todo("premium calculation yielding 197.5 G → final premium rounds up to 198 G");

  // Integration examples
  it.todo(
    "newcomer with cursed sword (steel, enchantment 3) → premium 165 G (100 base + 50 curse + 10 first insurance = 160 + 5 fee)"
  );
  it.todo(
    "long-standing customer's (3 years) second quote with cursed sword (enchantment 7) → premium 160 G " +
      "(100 base + 50 curse + 30 high enchantment - 20 loyalty + 10 first insurance - 15 follow-up = 155 + 5 fee); " +
      "each item in a quote is treated as first insurance regardless of customer history"
  );
});

