export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteResult {
  premium: number;
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const PROCESSING_FEE = 5;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const countByType = (items: QuoteItem[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

export const quote = (
  customer: Customer,
  items: QuoteItem[],
  contractIndex: number
): QuoteResult => {
  const counts = countByType(items);
  let policyBase = 0;
  for (const [type, count] of counts) {
    if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
      policyBase += COMPONENT_BLOCK_PREMIUM;
    } else {
      policyBase += BASE_PREMIUMS[type] * count;
    }
  }
  // Multiply-then-divide by whole numbers (not `* 1.1`) keeps this exact for
  // the bases seen so far — no float epsilon hack needed. Revisit with
  // Math.ceil/rounding once a test produces a genuinely fractional subtotal.
  const subtotal = (policyBase * 11) / 10;
  const premium = subtotal + PROCESSING_FEE;
  return { premium };
};

