export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteResult {
  premium: number;
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const PROCESSING_FEE = 5;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const countByType = (items: QuoteItem[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

// A component type (rune/moonstone) prices as a flat block premium when
// exactly COMPONENT_BLOCK_SIZE of that type are present; otherwise every
// item (component or not) prices per-unit from BASE_PREMIUMS.
const basePremiumForTypeCount = (type: string, count: number): number => {
  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
    return COMPONENT_BLOCK_PREMIUM;
  }
  return BASE_PREMIUMS[type] * count;
};

// NOTE: assumes the item's per-unit base price is BASE_PREMIUMS[item.type],
// which is true for all currently-tested cases (including lone/non-block
// components). This is NOT yet verified for a cursed component that's part
// of a priced block-of-3 (block premium is 20/item effective, not 25/item) —
// no test covers that combination yet, so this is left as-is pending one.
const curseSurcharge = (item: QuoteItem): number =>
  item.cursed ? BASE_PREMIUMS[item.type] / 2 : 0;

const HIGH_ENCHANTMENT_THRESHOLD = 5;

const enchantmentSurcharge = (item: QuoteItem): number =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
    ? (BASE_PREMIUMS[item.type] * 3) / 10
    : 0;

export const quote = (
  customer: Customer,
  items: QuoteItem[],
  contractIndex: number
): QuoteResult => {
  const counts = countByType(items);
  // Renamed from `policyBase`: this now accumulates per-type base premiums
  // AND per-item surcharges (curse, enchantment) below — i.e. everything
  // computed at the item level, before any policy-wide modifier (loyalty,
  // first insurance, follow-up discount) is applied.
  let itemLevelSubtotal = 0;
  for (const [type, count] of counts) {
    itemLevelSubtotal += basePremiumForTypeCount(type, count);
  }
  // Separate loop (not folded into the block above): curse/enchantment
  // surcharges are per-item modifiers, while the loop above is inherently
  // per-type-count (block-of-3 pricing can't be computed one item at a
  // time). Kept as a direct sum rather than an array-of-modifiers + reduce:
  // with just two modifiers, `curseSurcharge(item) + enchantmentSurcharge(item)`
  // is lower mass AND reads more directly than iterating a modifier array.
  // Revisit the array/reduce abstraction if a third per-item modifier appears.
  for (const item of items) {
    itemLevelSubtotal += curseSurcharge(item) + enchantmentSurcharge(item);
  }
  const subtotal = applyAlwaysOnFirstInsuranceSurcharge(itemLevelSubtotal);
  const premium = Math.ceil(subtotal + PROCESSING_FEE);
  return { premium };
};

// NEXT ARCHITECTURAL PRESSURE POINT: per spec, first-insurance surcharge,
// loyalty discount, and follow-up-contract discount are all POLICY-WIDE
// modifiers applied once to itemLevelSubtotal (unlike curse/enchantment,
// which are per-item). Today this function only ever applies the 10%
// first-insurance surcharge, unconditionally, regardless of `customer` or
// `contractIndex` — both currently unused by `quote`. That is incomplete:
// the surcharge should only apply on a customer's first contract, and
// loyalty/follow-up discounts (not yet implemented at all) belong here too.
// Multiply-then-divide by whole numbers (not `* 1.1`) avoids float epsilon
// errors for the bases seen so far. The result is intentionally left as a
// fraction (e.g. 192.5) — per spec, only the final premium is rounded, via
// the single Math.ceil at the call site.
