33	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
34	  }
35	  return counts;
36	};
37	
38	// A component type (rune/moonstone) prices as a flat block premium when
39	// exactly COMPONENT_BLOCK_SIZE of that type are present; otherwise every
40	// item (component or not) prices per-unit from BASE_PREMIUMS.
41	const basePremiumForTypeCount = (type: string, count: number): number => {
42	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
43	    return COMPONENT_BLOCK_PREMIUM;
44	  }
45	  return BASE_PREMIUMS[type] * count;
46	};
47	
48	// NOTE: assumes the item's per-unit base price is BASE_PREMIUMS[item.type],
49	// which is true for all currently-tested cases (including lone/non-block
50	// components). This is NOT yet verified for a cursed component that's part
51	// of a priced block-of-3 (block premium is 20/item effective, not 25/item) —
52	// no test covers that combination yet, so this is left as-is pending one.
53	const curseSurcharge = (item: QuoteItem): number =>
54	  item.cursed ? BASE_PREMIUMS[item.type] / 2 : 0;
55	
56	const HIGH_ENCHANTMENT_THRESHOLD = 5;
57	
58	const enchantmentSurcharge = (item: QuoteItem): number =>
59	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
60	    ? (BASE_PREMIUMS[item.type] * 3) / 10
61	    : 0;
62	
63	const LOYALTY_THRESHOLD_YEARS = 2;
64	
65	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
66	const LOYALTY_DISCOUNT_PERCENT = 20;
67	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
68	
69	// All policy-wide percentages are expressed out of 100, consistently, so
70	// they read as directly comparable rates (10%, 20%, 15%) rather than mixed
71	// tenths/hundredths fractions.
72	const percentOf = (percent: number, amount: number): number => (amount * percent) / 100;
73	
74	// Policy-wide modifiers (loyalty, first insurance, follow-up contract) are
75	// all percentages of the pure policy base premium (sum of item base
76	// premiums, before curse/enchantment surcharges), summed together — not
77	// compounded. First-insurance surcharge always applies (per spec, every
78	// item in a quote is treated as first insurance regardless of customer
79	// history); follow-up-contract discount additionally applies whenever this
80	// is not the customer's first quote in the scenario (contractIndex > 0).
81	const policyWideModifiers = (
82	  customer: Customer,
83	  policyBase: number,
84	  contractIndex: number
85	): number => {
86	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBase);
87	  const loyaltyDiscount =
88	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
89	      ? percentOf(LOYALTY_DISCOUNT_PERCENT, policyBase)
90	      : 0;
91	  const followUpDiscount =
92	    contractIndex > 0 ? percentOf(FOLLOW_UP_DISCOUNT_PERCENT, policyBase) : 0;
93	  return firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
94	};
95	
96	export const quote = (
97	  customer: Customer,
98	  items: QuoteItem[],
99	  contractIndex: number
100	): QuoteResult => {
101	  const counts = countByType(items);
102	  let policyBase = 0;
103	  for (const [type, count] of counts) {
104	    policyBase += basePremiumForTypeCount(type, count);
105	  }
106	  // itemLevelSubtotal starts from the pure policy base and adds per-item
107	  // surcharges (curse, enchantment). Separate loop from the block above:
108	  // curse/enchantment surcharges are per-item modifiers, while the loop
109	  // above is inherently per-type-count (block-of-3 pricing can't be
110	  // computed one item at a time). Kept as a direct sum rather than an
111	  // array-of-modifiers + reduce: with just two modifiers, this is lower
112	  // mass AND reads more directly than iterating a modifier array. Revisit
113	  // the array/reduce abstraction if a third per-item modifier appears.
114	  let itemLevelSubtotal = policyBase;
115	  for (const item of items) {
116	    itemLevelSubtotal += curseSurcharge(item) + enchantmentSurcharge(item);
117	  }
118	  // Multiply-then-divide by whole numbers (not `* 1.1`) avoids float
119	  // epsilon errors for the bases seen so far. The subtotal is intentionally
120	  // left as a fraction — per spec, only the final premium is rounded, via
121	  // the single Math.ceil below.
122	  const subtotal =
123	    itemLevelSubtotal + policyWideModifiers(customer, policyBase, contractIndex);
124	  const premium = Math.ceil(subtotal + PROCESSING_FEE);
125	  return { premium };
126	};

