export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

export const claim = (
  policyItems: PolicyItem[],
  damages: Damage[],
  priorPayouts: number
): ClaimResult => {
  const insuranceSum = policyItems.reduce(
    (sum, item) => sum + INSURANCE_VALUES[item.type],
    0
  );
  const cap = insuranceSum * CAP_MULTIPLIER;
  const totalPayout = damages.reduce(
    (sum, damage) => sum + Math.max(0, damage.amount - DEDUCTIBLE),
    0
  );
  return { payout: totalPayout, remainingCap: cap - priorPayouts - totalPayout };
};

