// Per-damage payout: full reimbursement minus the flat deductible, floored at
// 0. Named separately (mirrors quote.ts's per-item helpers like
// curseSurcharge/enchantmentSurcharge) as the single extension point for the
// upcoming reimbursement clauses (high-enchantment 50%, dragon-material full
// reimbursement), which modify this per-damage calculation before the
// deductible is applied.
const payoutForDamage = (damage: Damage): number =>
  Math.max(0, damage.amount - DEDUCTIBLE);

export const claim = (
  policyItems: PolicyItem[],
  damages: Damage[],
  priorPayouts: number
): ClaimResult => {
  const insuranceSum = policyItems.reduce(
    (sum, item) => sum + INSURANCE_VALUES[item.type],
    0
  );
  const cap = insuranceSum * CAP_MULTIPLIER;
  const totalPayout = damages.reduce(
    (sum, damage) => sum + payoutForDamage(damage),
    0
  );
  return { payout: totalPayout, remainingCap: cap - priorPayouts - totalPayout };
};

input.new_string:
const HIGH_ENCHANTMENT_THRESHOLD = 8;

// Per-damage payout: reimbursement clauses (based on the damaged item's
// properties) apply to the raw damage amount first, then the flat
// deductible is subtracted, floored at 0.
const payoutForDamage = (damage: Damage, item: PolicyItem): number => {
  const reimbursed =
    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
      ? damage.amount / 2
      : damage.amount;
  return Math.max(0, reimbursed - DEDUCTIBLE);
};

export const claim = (
  policyItems: PolicyItem[],
  damages: Damage[],
  priorPayouts: number
): ClaimResult => {
  const insuranceSum = policyItems.reduce(
    (sum, item) => sum + INSURANCE_VALUES[item.type],
    0
  );
  const cap = insuranceSum * CAP_MULTIPLIER;
  const totalPayout = damages.reduce((sum, damage) => {
    const item = policyItems.find((i) => i.type === damage.itemType)!;
    return sum + payoutForDamage(damage, item);
  }, 0);
  return { payout: totalPayout, remainingCap: cap - priorPayouts - totalPayout };
};

