export const claim = (
  policyItems: PolicyItem[],
  damages: Damage[],
  priorPayouts: number
): ClaimResult => {
  const insuranceSum = policyItems.reduce(
    (sum, item) => sum + INSURANCE_VALUES[item.type],
    0
  );
  const cap = insuranceSum * CAP_MULTIPLIER;
  const totalPayout = damages.reduce((sum, damage) => {
    // KNOWN GAP (deferred to future Red/Green cycles, not fixed here):
    // 1. Non-null assertion assumes a matching item always exists. Per spec,
    //    a damage referencing an item not in the policy must be REJECTED
    //    (throw), not silently produce `undefined` and crash inside
    //    payoutForDamage. Needs an explicit validation step once those
    //    "unknown item" / "item not in policy" tests are added.
    // 2. `.find` only returns the FIRST item of a matching type. Once tests
    //    cover multiple items of the same type (e.g. two swords, two sword
    //    damages), this will need one-to-one matching instead of always
    //    reusing the first match.
    // 3. Negative `damage.amount` (e.g. -200) is not validated/rejected; it
    //    would currently just be floored to a 0 payout by Math.max inside
    //    payoutForDamage instead of throwing. Needs an explicit guard once
    //    that "negative amount" test is added.
    const item = policyItems.find((i) => i.type === damage.itemType)!;
    return sum + payoutForDamage(damage, item);
  }, 0);
  return { payout: totalPayout, remainingCap: cap - priorPayouts - totalPayout };
};

