// Groups policy items by type into per-type pools so each damage entry can
// consume (remove) one matching item, enforcing a one-to-one match between
// damages and insured items of that type.
const groupByType = (items: PolicyItem[]): Map<string, PolicyItem[]> => {
  const pools = new Map<string, PolicyItem[]>();
  for (const item of items) {
    const pool = pools.get(item.type) ?? [];
    pool.push(item);
    pools.set(item.type, pool);
  }
  return pools;
};

export const claim = (
  policyItems: PolicyItem[],
  damages: Damage[],
  priorPayouts: number
): ClaimResult => {
  const insuranceSum = policyItems.reduce(
    (sum, item) => sum + INSURANCE_VALUES[item.type],
    0
  );
  const cap = insuranceSum * CAP_MULTIPLIER;
  const pools = groupByType(policyItems);
  // KNOWN GAP (deferred to future Red/Green cycles, not fixed here):
  // Negative `damage.amount` (e.g. -200) is not validated/rejected; it
  // would currently just be floored to a 0 payout by Math.max inside
  // payoutForDamage instead of throwing. Needs an explicit guard once that
  // "negative amount" test is added.
  const totalPayout = damages.reduce((sum, damage) => {
    const pool = pools.get(damage.itemType);
    const item = pool?.pop();
    if (!item) {
      throw new Error(
        `Damage references item type "${damage.itemType}" not covered (or already exhausted) by the policy`
      );
    }
    return sum + payoutForDamage(damage, item);
  }, 0);
  return { payout: totalPayout, remainingCap: cap - priorPayouts - totalPayout };
};

