1	export interface PolicyItem {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface Damage {
9	  itemType: string;
10	  amount: number;
11	}
12	
13	export interface ClaimResult {
14	  payout: number;
15	  remainingCap: number;
16	}
17	
18	const INSURANCE_VALUES: Record<string, number> = {
19	  sword: 1000,
20	  amulet: 600,
21	  staff: 800,
22	  potion: 400,
23	  rune: 250,
24	  moonstone: 250,
25	};
26	
27	const DEDUCTIBLE = 100;
28	const CAP_MULTIPLIER = 2;
29	
30	const HIGH_ENCHANTMENT_THRESHOLD = 8;
31	
32	// Per-damage payout: reimbursement clauses (based on the damaged item's
33	// properties) apply to the raw damage amount first, then the flat
34	// deductible is subtracted, floored at 0.
35	//
36	// Per spec there are two clauses: high-enchantment (>=8) reimburses at
37	// 50%, and dragon material reimburses fully, with the 50% rule winning if
38	// both apply. Only the 50% clause is checked below: "full reimbursement"
39	// is already this function's fallback behavior for an item with neither
40	// clause, so `item.material === "dragon"` can never change the result —
41	// checking it would be a dead branch. This is a deliberate omission, not
42	// a missed requirement: no black-box test can distinguish the two paths.
43	const payoutForDamage = (damage: Damage, item: PolicyItem): number => {
44	  const reimbursed =
45	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
46	      ? damage.amount / 2
47	      : damage.amount;
48	  return Math.max(0, reimbursed - DEDUCTIBLE);
49	};
50	
51	// Builds one consumable pool of policy items per type. Each pool is later
52	// drained (via pop) as damages are matched, one item per damage, enforcing
53	// a one-to-one match between damages and insured items of that type.
54	//
55	// Named distinctly from quote.ts's `countByType` on purpose: that helper
56	// returns read-only per-type counts, while this one returns arrays meant to
57	// be mutated (drained) by the caller.
58	const buildItemPoolsByType = (items: PolicyItem[]): Map<string, PolicyItem[]> => {
59	  const pools = new Map<string, PolicyItem[]>();
60	  for (const item of items) {
61	    const pool = pools.get(item.type) ?? [];
62	    pool.push(item);
63	    pools.set(item.type, pool);
64	  }
65	  return pools;
66	};
67	
68	export const claim = (
69	  policyItems: PolicyItem[],
70	  damages: Damage[],
71	  priorPayouts: number
72	): ClaimResult => {
73	  const insuranceSum = policyItems.reduce(
74	    (sum, item) => sum + INSURANCE_VALUES[item.type],
75	    0
76	  );
77	  const cap = insuranceSum * CAP_MULTIPLIER;
78	  const pools = buildItemPoolsByType(policyItems);
79	  // KNOWN GAP (deferred to future Red/Green cycles, not fixed here):
80	  // Negative `damage.amount` (e.g. -200) is not validated/rejected; it
81	  // would currently just be floored to a 0 payout by Math.max inside
82	  // payoutForDamage instead of throwing. Needs an explicit guard once that
83	  // "negative amount" test is added.
84	  const desiredPayout = damages.reduce((sum, damage) => {
85	    const pool = pools.get(damage.itemType);
86	    const item = pool?.pop();
87	    if (!item) {
88	      throw new Error(
89	        `Damage references item type "${damage.itemType}" not covered (or already exhausted) by the policy`
