    // base 175 + 10% first insurance (17.5) = 192.5 + 5 fee = 197.5 -> rounds up to 198
    expect(result.premium).toBe(198);
  });
  it("2 runes + 1 moonstone → 75 G base premium (no block: different types)", () => {
    const result = quote(
      { yearsWithMHPCO: 0 },
      [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
